function unq(v) {
  if (typeof v !== 'string') return v;
  try { const p = JSON.parse(v); return typeof p === 'string' ? p : v; } catch { return v.replace(/^"|"$/g, ''); }
}
// Stacked horizontal bar by sub-topic / sentiment.
const rows = $input.all().map(i => i.json);
const subtopicTotals = {};
const cells = {}; // subtopic -> {positive, neutral, negative}
for (const r of rows) {
  const sub = String(unq(r.subtopic) ?? 'unknown');
  let sent = String(r.sentiment ?? '').toLowerCase().replace(/"/g,'');
  if (!['positive','negative','neutral'].includes(sent)) continue;
  const cnt = Number(r.cnt || 0);
  cells[sub] = cells[sub] || { positive:0, neutral:0, negative:0 };
  cells[sub][sent] += cnt;
  subtopicTotals[sub] = (subtopicTotals[sub] || 0) + cnt;
}
const sorted = Object.entries(subtopicTotals).sort((a,b) => b[1]-a[1]).slice(0, 10).map(e => e[0]);
const chartTitle = $('Set Params').first().json.chart_title;
const chartConfig = {
  type: 'bar',
  data: {
    labels: sorted,
    datasets: [
      { label: 'Positive', data: sorted.map(s => cells[s].positive), backgroundColor: '#59a14f' },
      { label: 'Neutral',  data: sorted.map(s => cells[s].neutral),  backgroundColor: '#edc948' },
      { label: 'Negative', data: sorted.map(s => cells[s].negative), backgroundColor: '#e15759' },
    ]
  },
  options: {
    indexAxis: 'y',
    plugins: { title: { display: true, text: chartTitle } },
    scales: { x: { stacked: true }, y: { stacked: true } }
  }
};
return [{ json: { status: "success", content: { ...chartConfig, type: 'bar' } } }];
